
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_b88_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_b88", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.322854096915606e+00, -4.241122392104273e+00, -4.126686653548032e+00, -3.968352647187409e+00, -3.752994312320948e+00, -3.467182717412648e+00, -3.100982290501078e+00, -2.654679055071531e+00, -2.147341894195304e+00, -1.618694798668896e+00, -1.100263985053823e+00, -7.121791858585917e-01, -6.041998946917908e-01, -5.040189843219982e-01, -3.726133099015326e-01, -2.478714125552524e-01, -1.554696146880382e-01, -9.599718637285722e-02, -6.101526749214398e-02, -4.172015377427103e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


